            for (int y = 0; y < targetHeight; y++) {
                for (int x = 0; x < targetWidth; x++) {
                    newSum += destImage.getRGB(x, y);
                }
            }

            assert originalSum != newSum : "Destination image should be modified by the resizer";
            System.out.println("__CHECK__ ProgressiveBilinearResizer resized image, pixel sum changed from " + originalSum + " to " + newSum);
